-- 0003_kernel_field_permissions
-- Forward-only migration (rule 34). Covered by packages/kernel/src/__tests__/masking.integration.test.ts.
-- Field visibility per role (rule 14, design §5.3): the rules live here, the per-entity masked
-- views that apply them are generated by maskedViewSql (packages/kernel/src/security).

create table kernel.field_permissions (
  id         uuid primary key default kernel.uuid_v7(),
  company_id uuid not null references kernel.companies (id),
  role_id    uuid not null references kernel.roles (id) on delete cascade,
  entity     text not null,
  field      text not null,
  mode       text not null check (mode in ('visible', 'masked', 'hidden')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid default kernel.current_user_id(),
  updated_by uuid,
  unique (company_id, role_id, entity, field)
);
create index field_permissions_role_id_idx on kernel.field_permissions (role_id);

create trigger field_permissions_touch_updated before update on kernel.field_permissions
  for each row execute function kernel.touch_updated();

grant select, insert, update, delete on kernel.field_permissions to authenticated;
grant all on kernel.field_permissions to service_role;

-- Everybody in the active company reads the rules; only its admin writes them, and only for roles
-- of that company (the restrictive policies are ANDed with company_isolation).
select kernel.enable_company_rls('kernel', 'field_permissions');
create policy admin_insert on kernel.field_permissions as restrictive for insert to authenticated
  with check (
    (select kernel.is_company_admin())
    and exists (select 1 from kernel.roles r where r.id = role_id and r.company_id = field_permissions.company_id)
  );
create policy admin_update on kernel.field_permissions as restrictive for update to authenticated
  using ((select kernel.is_company_admin()))
  with check (
    (select kernel.is_company_admin())
    and exists (select 1 from kernel.roles r where r.id = role_id and r.company_id = field_permissions.company_id)
  );
create policy admin_delete on kernel.field_permissions as restrictive for delete to authenticated
  using ((select kernel.is_company_admin()));

select kernel.enable_row_audit('kernel', 'field_permissions');

-- ---------------------------------------------------------------------------------------------
-- Resolution. The caller's roles (claim role_ids, active company) are combined with the most
-- restrictive mode winning: hidden > masked > visible; no row means visible. Security definer so
-- the masked views work for any caller whatever the grants on the table are.
-- ---------------------------------------------------------------------------------------------
create or replace function kernel.field_mode(entity text, field text) returns text
language sql stable security definer parallel safe
set search_path = ''
as $$
  select coalesce(
    (
      select case max(case fp.mode when 'hidden' then 3 when 'masked' then 2 else 1 end)
               when 3 then 'hidden'
               when 2 then 'masked'
               else 'visible'
             end
      from kernel.field_permissions fp
      where fp.company_id = kernel.current_company_id()
        and array[fp.company_id] <@ kernel.current_company_ids()
        and fp.role_id = any (kernel.current_role_ids())
        and fp.entity = field_mode.entity
        and fp.field = field_mode.field
    ),
    'visible'
  );
$$;

-- True only when the field is shown as it is; masked and hidden both read as null through the view.
create or replace function kernel.field_visible(entity text, field text) returns boolean
language sql stable security definer parallel safe
set search_path = ''
as $$
  select kernel.field_mode(field_visible.entity, field_visible.field) = 'visible';
$$;

revoke execute on function kernel.field_mode(text, text), kernel.field_visible(text, text) from public;
grant execute on function kernel.field_mode(text, text), kernel.field_visible(text, text) to authenticated, service_role;

-- ---------------------------------------------------------------------------------------------
-- Masking of the admin-defined extra data (design §5.14, rule 14). Returns `p_extra` without the keys
-- whose kernel.custom_fields definition (0008) does not list a role of the caller in roles_view; a key
-- nobody defined (its definition was removed) is stripped too, so removing a field never exposes the
-- data it protected. The masked views call it for the `extra` column, so grids, exports, the assistant
-- and the consults see the same thing. It lives with the other masking functions and is plpgsql so
-- kernel.custom_fields is resolved when it runs (the table is created by 0008, after the views of 0006
-- that call this function). Security definer: the caller needs no grant on the definitions.
-- ---------------------------------------------------------------------------------------------
create or replace function kernel.mask_extra(p_entity text, p_extra jsonb) returns jsonb
language plpgsql stable security definer parallel safe
set search_path = ''
as $$
begin
  if p_extra is null or p_extra = '{}'::jsonb then
    return p_extra;
  end if;
  if jsonb_typeof(p_extra) <> 'object' or not array[kernel.current_company_id()] <@ kernel.current_company_ids() then
    return '{}'::jsonb;
  end if;
  return coalesce(
    (
      select jsonb_object_agg(e.key, e.value)
      from jsonb_each(p_extra) as e
      where exists (
        select 1
        from kernel.custom_fields cf
        where cf.company_id = kernel.current_company_id()
          and cf.entity = p_entity
          and cf.key = e.key
          and cf.roles_view && kernel.current_role_ids()
      )
    ),
    '{}'::jsonb
  );
end;
$$;
revoke execute on function kernel.mask_extra(text, jsonb) from public, anon;
grant execute on function kernel.mask_extra(text, jsonb) to authenticated, service_role;
